package com.chengukargbo.careeros.questions;
import java.util.List; import java.util.Optional; import org.springframework.data.jpa.repository.JpaRepository; import com.chengukargbo.careeros.questions.QuestionEnums.*;
interface QuestionTemplateRepository extends JpaRepository<QuestionTemplate,Long>{List<QuestionTemplate> findByJobFamilyAndActiveTrueOrderByCanonicalQuestionKeyAsc(JobFamily family);List<QuestionTemplate> findByActiveTrueOrderByCanonicalQuestionKeyAsc();}
interface ApplicationQuestionRepository extends JpaRepository<ApplicationQuestion,Long>{List<ApplicationQuestion> findByApplicationIdOrderByIdAsc(Long id);List<ApplicationQuestion> findAllByOrderByApplicationIdAscIdAsc();boolean existsByApplicationIdAndTemplateId(Long a,Long t);Optional<ApplicationQuestion> findByApplicationIdAndExternalQuestionKey(Long applicationId,String externalQuestionKey);Optional<ApplicationQuestion> findFirstByApplicationIdAndCanonicalQuestionKeyOrderByIdAsc(Long applicationId,String canonicalQuestionKey);}
